    public static void split(Shape s,int index){Node a=s.nodes.get(index),b=s.nodes.get((index+1)%s.nodes.size());double q0x=a.x+a.ox/2,q0y=a.y+a.oy/2,q1x=(a.x+a.ox+b.x+b.ix)/2,q1y=(a.y+a.oy+b.y+b.iy)/2,q2x=b.x+b.ix/2,q2y=b.y+b.iy/2,r0x=(q0x+q1x)/2,r0y=(q0y+q1y)/2,r1x=(q1x+q2x)/2,r1y=(q1y+q2y)/2;Node n=new Node((r0x+r1x)/2,(r0y+r1y)/2);n.ix=r0x-n.x;n.iy=r0y-n.y;n.ox=r1x-n.x;n.oy=r1y-n.y;a.ox=q0x-a.x;a.oy=q0y-a.y;b.ix=q2x-b.x;b.iy=q2y-b.y;s.nodes.add(index+1,n);}
