    private static void simplify(List<Node> n,int a,int b,double eps,boolean[] keep){double best=eps;int at=-1;for(int i=a+1;i<b;i++){double d=distance(new double[]{n.get(i).x,n.get(i).y},new double[]{n.get(a).x,n.get(a).y},new double[]{n.get(b).x,n.get(b).y});if(d>best){best=d;at=i;}}if(at>=0){keep[at]=true;simplify(n,a,at,eps,keep);simplify(n,at,b,eps,keep);}}
    private static double distance(double[] p,double[] a,double[] b){double x=b[0]-a[0],y=b[1]-a[1],u=(x*x+y*y)<1e-12?0:Math.max(0,Math.min(1,((p[0]-a[0])*x+(p[1]-a[1])*y)/(x*x+y*y)));return Math.hypot(p[0]-a[0]-u*x,p[1]-a[1]-u*y);}
