    private static String nativeShape(Shape s,long id,String label,int start,int end){if(Math.abs(s.sx)<1e-9||Math.abs(s.sy)<1e-9)return "";if(s.isImage())return nativeImage(s,id,label,start,end);String tag=s.isText()?"text":"shape";StringBuilder x=new StringBuilder("<").append(tag).append(" id=\"").append(id).append("\" label=\"").append(escape(label)).append("\" startTime=\"").append(start).append("\" endTime=\"").append(end).append("\" fillType=\"color\"");String holes=s.holeMarker();if(!holes.isEmpty())x.append(" templatePPId=\"").append(holes).append("\"");if(s.isText())x.append(" size=\"").append(n(s.fontSize)).append("\" wrapWidth=\"").append(n(Math.max(s.fontSize*2,s.text.length()*s.fontSize))).append("\" align=\"CENTER\"");x.append("><transform><location value=\"").append(n(s.x)).append(',').append(n(s.y)).append(",0\"/><scale value=\"").append(n(s.sx)).append(',').append(n(s.sy)).append("\"/><rotation value=\"").append(n(s.angle)).append("\"/><opacity value=\"").append(n(s.opacity)).append("\"/></transform><fillColor value=\"").append(hex(s.fill)).append("\"/>");if(s.isText())x.append("<content>").append(escape(s.text)).append("</content>");else{x.append("<path d=\"").append(s.path()).append("\"/>");if(s.strokeWidth>0&&(s.stroke>>>24)>0)x.append("<path-stroke direction=\"centered\" end-size=\"1\"><size value=\"").append(n(s.strokeWidth)).append("\"/><color value=\"").append(hex(s.stroke)).append("\"/></path-stroke>");}return x.append("</").append(tag).append('>').toString();}
